"""새로 작성한 자외선·보관 300사례의 입력 우선 조립. 외부 검수기가 아니다."""
from __future__ import annotations

import hashlib
import json
from pathlib import Path
import sys

COS = Path(__file__).resolve().parents[5]
sys.path.insert(0, str(COS))
from scripts.validate_qlora_dataset import SYSTEM_PROMPT_SOLUTION_HOLD
from beauty_agent.v3_contracts import SLMRequest

HERE = Path(__file__).resolve().parents[1]
POOL = {x['evidence_ref']: x for x in (json.loads(l) for l in (COS/'data/rag/chunks.jsonl').read_text(encoding='utf-8').splitlines())}
FAMILIES = []
HOLD_FAMILIES = []


def family(name, ref, reason, cases, *, hn=None, val=False):
    assert len(cases) == 5, (name, len(cases))
    FAMILIES.append(dict(name=name, ref='ref:'+ref, reason=reason, cases=cases, hn=hn, val=val))


def holds(name, cases, *, val=False):
    assert len(cases) == 5
    HOLD_FAMILIES.append(dict(name=name, cases=cases, val=val))


